53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const isComponent = (item: QuoteItem): boolean =>
69	  COMPONENT_TYPES.includes(item.type);
70	
71	const basePremiumOf = (item: QuoteItem): number => BASE_PREMIUMS[item.type];
72	
73	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
74	  values.reduce((sum, value) => sum + amount(value), 0);
75	
76	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
77	const componentTypePremium = (items: QuoteItem[], type: string): number => {
78	  const count = items.filter((item) => item.type === type).length;
79	  return count === COMPONENT_BLOCK_SIZE
80	    ? COMPONENT_BLOCK_PREMIUM
81	    : count * BASE_PREMIUMS[type];
82	};
83	
84	const quotePremium = (items: QuoteItem[]): number => {
85	  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
86	    componentTypePremium(items, type)
87	  );
88	  const mainItemsPremium = sumBy(
89	    items.filter((item) => !isComponent(item)),
90	    basePremiumOf
91	  );
92	  const policyBasePremium = componentsPremium + mainItemsPremium;
93	  const curseSurcharge = sumBy(
94	    items.filter((item) => item.cursed),
95	    (item) => basePremiumOf(item) / 2
96	  );
97	  const enchantmentSurcharge = sumBy(
98	    items.filter((item) => (item.enchantment ?? 0) >= 5),
99	    (item) => (basePremiumOf(item) * 3) / 10
100	  );
101	  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
102	  const firstInsuranceSurcharge = policyBasePremium / 10;
103	  return Math.ceil(
104	    policyBasePremium +
105	      curseSurcharge +
106	      enchantmentSurcharge +
107	      firstInsuranceSurcharge +
108	      PROCESSING_FEE
109	  );
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResult => {
113	  const quoteStep = scenario.steps[0] as QuoteStep;
114	  return { results: [{ premium: quotePremium(quoteStep.items) }] };
115	};
